bench( pkg+':reproducible', function benchmark( b ) {
	var rng1;
	var rng2;
	var v1;
	var v2;
	var i;

	rng1 = xorshift128plus({
		'seed': BigInt(54321)
	});
	rng2 = xorshift128plus({
		'seed': BigInt(54321)
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v1 = rng1();
		v2 = rng2();
		if ( v1 !== v2 ) {
			b.fail( 'sequences should be identical' );
		}
	}
	b.toc();

	if ( v1 !== v2 ) {
		b.fail( 'sequences should be identical' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':batch:next', function benchmark( b ) {
	var values;
	var rng;
	var i;
	var j;

	rng = xorshift128plus({
		'seed': BigInt(12345)
	});
	values = [];
	values.length = 100;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		for ( j = 0; j < 100; j++ ) {
			values[ j ] = rng();
		}
	}
	b.toc();

	if ( values.length !== 100 ) {
		b.fail( 'invalid values array length' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':batch:normalized', function benchmark( b ) {
	var values;
	var rng;
	var i;
	var j;

	rng = xorshift128plus({
		'seed': BigInt(12345)
	});
	values = [];
	values.length = 100;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		for ( j = 0; j < 100; j++ ) {
			values[ j ] = rng.normalized();
		}
	}
	b.toc();

	if ( values.length !== 100 ) {
		b.fail( 'invalid values array length' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':mixed', function benchmark( b ) {
	var rng;
	var v1;
	var v2;
	var i;

	rng = xorshift128plus({
		'seed': BigInt(12345)
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v1 = rng();
		v2 = rng.normalized();
	}
	b.toc();

	if ( !isBigInt( v1 ) ) {
		b.fail( 'should return a BigInt' );
	}
	if ( typeof v2 !== 'number' ) {
		b.fail( 'should return a number' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
